var a=`1403-kokoda`;var n=`world-1403`;var o=`FJ`;var t=`oceania`;var s=4;var c=45;var l={en:`Kokoda`,ua:`Кокода`};var r={en:`Fijian coconut-and-lime fish salad. Traditionally made with raw marinated fish; this safer home version uses fully cooked, chilled fish.`,ua:`Фіджійський рибний салат із кокосовими вершками та лаймом. Традиційно рибу маринують сирою; ця домашня версія використовує повністю приготовлену й охолоджену рибу.`};var d=[{en:`Poach fish gently in just-simmering water until its centre reaches 63°C; remove and chill promptly in a shallow covered dish.`,ua:`Обережно припустіть рибу в ледь киплячій воді до температури 63°C у центрі; дістаньте та швидко охолодіть у неглибокому накритому посуді.`,t:[`poaching`],m:12,i:[[`mahi-mahi`,600,`g`],[`water`,700,`ml`]]},{en:`Dice the cooled fish. Mix with lime juice in a clean bowl and refrigerate for 15 minutes; the citrus seasons already cooked fish rather than cooking it.`,ua:`Наріжте охолоджену рибу кубиками. Змішайте з соком лайма в чистій мисці та поставте в холодильник на 15 хвилин; цитрус лише маринує вже приготовлену рибу.`,t:[`acid-marination`],m:15,i:[[`lime-juice`,110,`ml`]]},{en:`Finely chop red onion, tomato, cucumber and chili; toss into the fish.`,ua:`Дрібно наріжте червону цибулю, помідори, огірок і чилі та додайте до риби.`,t:[`dicing`,`mixing`],m:8,i:[[`red-onion`,75,`g`],[`tomato`,150,`g`],[`cucumber`,140,`g`],[`bird-s-eye-chili`,1,`pcs`]]},{en:`Fold in chilled coconut cream and salt; refrigerate briefly and serve cold.`,ua:`Обережно додайте охолоджені кокосові вершки й сіль; ненадовго охолодіть і подавайте холодним.`,t:[`folding-in`,`seasoning`],m:10,i:[[`coconut-cream`,230,`ml`],[`sea-salt`,4,`g`]]}];var h={slug:a,id:n,country:`FJ`,region:t,servings:4,minutes:45,title:l,text:r,steps:d};export{o as country,h as default,n as id,c as minutes,t as region,s as servings,a as slug,d as steps,r as text,l as title};